import os,time,hashlib
def sample_reads(path,offsets,size):
    if not isinstance(offsets,list) or not 1<=len(offsets)<=128 or any(type(x) is not int or x<0 for x in offsets):raise ValueError('offsets')
    if type(size) is not int or not 1<=size<=65536:raise ValueError('block size')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
    try:
        calls=total=0;digest=hashlib.sha256();started=time.monotonic_ns()
        for offset in offsets:
            completed=0
            while completed<size:
                block=os.pread(fd,size-completed,offset+completed);calls+=1
                if not block:raise EOFError('short logical request at EOF')
                completed+=len(block);total+=len(block);digest.update(block)
        elapsed=(time.monotonic_ns()-started)/1_000_000_000
        if elapsed<=0:raise RuntimeError('clock did not advance')
        return {'completed_requests':len(offsets),'pread_calls':calls,'bytes':total,'seconds':elapsed,
                'logical_iops':len(offsets)/elapsed,'syscall_iops':calls/elapsed,
                'physical_iops':None,'sha256':digest.hexdigest()}
    finally:os.close(fd)
