import math
from pathlib import Path
def disk_snapshot(path='/proc/diskstats'):
    result={}
    for line in Path(path).read_text(encoding='ascii').splitlines():
        if not line.strip():continue
        fields=line.split()
        if len(fields)<14 or any(not x.isascii() or not x.isdecimal() for x in fields[:2]+fields[3:]):raise ValueError('diskstats record')
        name=fields[2]
        if name in result:raise ValueError('duplicate device')
        values=[int(x) for x in fields[3:]]
        result[name]={'reads':values[0],'read_sectors':values[2],'writes':values[4],
            'write_sectors':values[6],'in_progress':values[8],'io_ms':values[9]}
    return result
def interval(before,after,seconds,device):
    if type(seconds) not in (int,float) or not math.isfinite(seconds) or seconds<=0:raise ValueError('interval')
    left=before[device];right=after[device]
    names=['reads','read_sectors','writes','write_sectors','io_ms']
    delta={name:right[name]-left[name] for name in names}
    if any(value<0 for value in delta.values()):raise ValueError('counter reset')
    return {'read_iops':delta['reads']/seconds,'write_iops':delta['writes']/seconds,
        'read_Bps':delta['read_sectors']*512/seconds,'write_Bps':delta['write_sectors']*512/seconds,
        'util_percent':delta['io_ms']/(seconds*1000)*100,'in_progress':right['in_progress'],
        'saturation_proven':False}
```

